// Calculate quarter date range
const body = $input.first().json.body || {};

// Get quarter and year from request or auto-detect
let quarter = body.quarter;
let year = body.year;

if (!quarter || !year) {
  const now = new Date();
  year = now.getFullYear();
  const month = now.getMonth();

  // Determine previous quarter
  if (month < 3) {
    quarter = 'Q4';
    year = year - 1;
  } else if (month < 6) {
    quarter = 'Q1';
  } else if (month < 9) {
    quarter = 'Q2';
  } else {
    quarter = 'Q3';
  }
}

const quarters = {
  'Q1': { start: `${year}-01-01`, end: `${year}-03-31` },
  'Q2': { start: `${year}-04-01`, end: `${year}-06-30` },
  'Q3': { start: `${year}-07-01`, end: `${year}-09-30` },
  'Q4': { start: `${year}-10-01`, end: `${year}-12-31` }
};

const dates = quarters[quarter];

return [{
  json: {
    quarter,
    year,
    startDate: dates.start,
    endDate: dates.end,
    reportName: `${quarter}_${year}_Tax_Export`
  }
}];

// Categorize and validate expenses for tax/audit purposes
const quarterData = $('Code - Calculate Quarter Range').first().json;
const expenseItems = $('Sheets - Get Quarter Expenses').all() || [];
const incomeItems = $('Sheets - Get Quarter Revenue').all() || [];

const startDate = new Date(quarterData.startDate);
const endDate = new Date(quarterData.endDate);

// Filter to quarter range
const quarterExpenses = expenseItems.filter(item => {
  const date = new Date(item.json.Date);
  return date >= startDate && date <= endDate;
}).map(e => e.json);

const quarterIncomes = incomeItems.filter(item => {
  const date = new Date(item.json.Date);
  return date >= startDate && date <= endDate && item.json.Type === 'Customer Payment';
}).map(i => i.json);

// IRS Category Mapping (aligned with your assistant's categories)
const irsCategoryMap = {
  'Software': 'Software',
  'Meals': 'Meals',
  'Travel': 'Travel',
  'Supplies': 'Office Expense',
  'Services': 'Legal and Professional Services',
  'Advertising': 'Advertising',
  'Equipment': 'Equipment',
  'Banking Fees': 'Bank Service Charges',
  'Miscellaneous': 'Other Business Expenses',
  'Uncategorized': 'Other Business Expenses'
};

// Categories that require special audit fields
const requiresBusinessPurpose = ['Meals', 'Travel', 'Services', 'Advertising'];
const requiresPeopleInvolved = ['Meals'];

const validatedExpenses = [];
const flaggedExpenses = [];
const auditIssues = [];

quarterExpenses.forEach(expense => {
  const category = expense.Category || 'Uncategorized';
  const irsCategory = irsCategoryMap[category] || 'Other Business Expenses';
  const receiptStatus = expense['Receipt Status'] || 'Missing';
  const hasReceipt = receiptStatus === 'Added';
  const businessPurpose = expense['Business Purpose'] || '';
  const peopleInvolved = expense['People Involved'] || '';
  const peopleRelationship = expense['People Relationship'] || '';
  const receiptItemized = expense['Receipt Itemized'] || 'No';

  const expenseData = {
    date: expense.Date || '',
    merchant: expense.Merchant || 'Unknown',
    amount: parseFloat(expense.Amount) || 0,
    paymentMethod: expense['Payment Method'] || '',
    cardLast4: expense['Card Last 4'] || '',
    category,
    irsCategory,
    businessPurpose,
    peopleInvolved,
    peopleRelationship,
    locationCity: expense['Location City'] || '',
    locationState: expense['Location State'] || '',
    venueType: expense['Venue Type'] || '',
    hasReceipt,
    receiptStatus,
    receiptUrl: expense['Receipt URL'] || '',
    receiptItemized,
    transactionId: expense['Transaction ID'] || '',
    notes: expense.Notes || '',
    rowNumber: expense.row_number
  };

  // Check audit compliance
  const issues = [];
  if (!hasReceipt) issues.push('Missing receipt');
  if (requiresBusinessPurpose.includes(category) && !businessPurpose) issues.push('Missing business purpose');
  if (requiresPeopleInvolved.includes(category) && !peopleInvolved) issues.push('Missing people involved');
  if (hasReceipt && receiptItemized !== 'Yes' && category === 'Meals') issues.push('Receipt not itemized');

  expenseData.auditIssues = issues;
  expenseData.isAuditCompliant = issues.length === 0;

  if (expenseData.isAuditCompliant) {
    validatedExpenses.push(expenseData);
  } else {
    flaggedExpenses.push(expenseData);
    if (issues.length > 0) {
      auditIssues.push({ ...expenseData, issues });
    }
  }
});

// Group by IRS category
const expensesByIRSCategory = {};
validatedExpenses.forEach(exp => {
  if (!expensesByIRSCategory[exp.irsCategory]) {
    expensesByIRSCategory[exp.irsCategory] = { total: 0, count: 0, items: [] };
  }
  expensesByIRSCategory[exp.irsCategory].total += exp.amount;
  expensesByIRSCategory[exp.irsCategory].count++;
  expensesByIRSCategory[exp.irsCategory].items.push(exp);
});

// Calculate revenue
const grossRevenue = quarterIncomes.reduce((sum, i) => sum + (parseFloat(i['Gross Amount']) || 0), 0);

// Revenue by month
const revenueByMonth = {};
quarterIncomes.forEach(income => {
  const dateStr = income.Date;
  if (dateStr) {
    const month = dateStr.substring(0, 7);
    revenueByMonth[month] = (revenueByMonth[month] || 0) + (parseFloat(income['Gross Amount']) || 0);
  }
});

// Totals
const totalDeductible = validatedExpenses.reduce((sum, exp) => sum + exp.amount, 0);
const totalFlagged = flaggedExpenses.reduce((sum, exp) => sum + exp.amount, 0);
const taxableIncome = grossRevenue - totalDeductible;
const estimatedTax = Math.max(0, taxableIncome * 0.25);

return [{
  json: {
    ...quarterData,
    validatedExpenses,
    flaggedExpenses,
    auditIssues,
    expensesByIRSCategory,
    revenue: { grossRevenue, revenueByMonth, transactionCount: quarterIncomes.length },
    totals: { totalDeductible, totalFlagged, taxableIncome, estimatedTax },
    auditSummary: {
      totalExpenses: quarterExpenses.length,
      compliant: validatedExpenses.length,
      nonCompliant: flaggedExpenses.length,
      complianceRate: quarterExpenses.length > 0 ? ((validatedExpenses.length / quarterExpenses.length) * 100).toFixed(1) : 0
    }
  }
}];

// Generate CSV export with full audit fields
const data = $input.first().json;
const { validatedExpenses, quarter, year } = data;

// CSV header aligned with audit requirements
let csv = 'Date,Merchant,Amount,Payment Method,Card Last 4,IRS Category,Category,Business Purpose,People Involved,People Relationship,Location City,Location State,Venue Type,Receipt URL,Receipt Itemized,Transaction ID,Notes\n';

// Add each expense
validatedExpenses.forEach(exp => {
  csv += `"${exp.date}",`;
  csv += `"${exp.merchant.replace(/"/g, '""')}",`;
  csv += `${exp.amount.toFixed(2)},`;
  csv += `"${exp.paymentMethod}",`;
  csv += `"${exp.cardLast4}",`;
  csv += `"${exp.irsCategory}",`;
  csv += `"${exp.category}",`;
  csv += `"${(exp.businessPurpose || '').replace(/"/g, '""')}",`;
  csv += `"${(exp.peopleInvolved || '').replace(/"/g, '""')}",`;
  csv += `"${(exp.peopleRelationship || '').replace(/"/g, '""')}",`;
  csv += `"${exp.locationCity}",`;
  csv += `"${exp.locationState}",`;
  csv += `"${exp.venueType}",`;
  csv += `"${exp.receiptUrl}",`;
  csv += `"${exp.receiptItemized}",`;
  csv += `"${exp.transactionId}",`;
  csv += `"${(exp.notes || '').replace(/"/g, '""')}"\n`;
});

return [{
  json: {
    ...data,
    csvContent: csv,
    csvFilename: `${quarter}_${year}_Deductible_Expenses.csv`
  }
}];

// Format Slack summary
const data = $input.first().json;
const { quarter, year, revenue, totals, flaggedExpenses } = data;
const sheetsUrl = `https://docs.google.com/spreadsheets/d/${$env.GOOGLE_SHEETS_FINANCE_ID}`;

let message = `:clipboard: *${quarter} ${year} Tax Prep Complete*\n\n`;
message += `*Gross Revenue:* $${revenue.grossRevenue.toFixed(2)}\n`;
message += `*Deductible Expenses:* $${totals.totalDeductible.toFixed(2)}\n`;
message += `*Estimated Tax:* $${totals.estimatedTax.toFixed(2)}\n\n`;

if (flaggedExpenses.length > 0) {
  message += `:warning: *Missing Receipts:* ${flaggedExpenses.length} items ($${totals.totalFlagged.toFixed(2)})\n\n`;
}

message += `*Documents ready:*\n`;
message += `• CSV Export\n`;
message += `• Detailed Email Summary\n\n`;
message += `Check your email for the full package.\n`;
message += `<${sheetsUrl}|View in Google Sheets>`;

return [{ json: { ...data, slackMessage: message } }];

